<?php $pageTitle='Shop — AMORA'; include 'includes/header.php'; $cat=$_GET['cat']??''; $q=$_GET['q']??''; $items=[]; if($pdo){$sql='SELECT * FROM products WHERE 1';$args=[];if($cat&&$cat!=='New'){$sql.=' AND category=?';$args[]=$cat;}if($cat==='New'){$sql.=" AND tag='NEW'";}if($q){$sql.=' AND (name LIKE ? OR category LIKE ?)';$args[]="%$q%";$args[]="%$q%";}$sql.=' ORDER BY featured DESC,id DESC';$st=$pdo->prepare($sql);$st->execute($args);$items=$st->fetchAll();} ?>
<section class="shop-hero"><p class="eyebrow">AMORA / COLLECTION</p><h1>Find your <em>form.</em></h1><p>Pieces made to shift the energy in a room.</p></section><div class="filters"><a class="<?=!$cat?'active':''?>" href="shop.php">All</a><a class="<?=$cat==='Dresses'?'active':''?>" href="shop.php?cat=Dresses">Dresses</a><a class="<?=$cat==='Tops'?'active':''?>" href="shop.php?cat=Tops">Tops</a><a class="<?=$cat==='Outerwear'?'active':''?>" href="shop.php?cat=Outerwear">Outerwear</a><a class="<?=$cat==='Bottoms'?'active':''?>" href="shop.php?cat=Bottoms">Bottoms</a><a class="<?=$cat==='New'?'active':''?>" href="shop.php?cat=New">New</a></div><section class="product-grid shop-grid"><?php foreach($items as $p): ?><a class="product" href="product.php?id=<?=$p['id']?>"><div class="product-img"><img src="<?=$p['image']?>" alt="<?=htmlspecialchars($p['name'])?>"><span class="pill"><?=htmlspecialchars($p['tag'])?></span><button onclick="event.preventDefault();addToCart(<?=$p['id']?>)">+</button></div><div class="product-info"><span><?=htmlspecialchars($p['category'])?></span><h3><?=htmlspecialchars($p['name'])?></h3><b>₦<?=number_format($p['price'])?></b></div></a><?php endforeach; ?></section><?php include 'includes/footer.php'; ?>
